import Hatchet from '../../sdk';
import { simpleCronWorkflow } from './cron-worker';
const hatchet = Hatchet.init();
// This example assumes you have a worker already running
// and registered the cron workflow to it
async function main() {
// ? Create
// You can create dynamic cron triggers programmatically via the API
const createdCron = await hatchet.cron.create(
simpleCronWorkflow, // workflow object or string workflow id
{
name: 'customer-a-daily-report', // friendly name for the cron trigger
expression: '0 12 * * *', // every day at noon
input: {
name: 'John Doe',
},
additionalMetadata: {
customerId: '123',
},
}
);
const { id } = createdCron.metadata; // id which you can later use to reference the cron trigger
// !!
...
// You can get a specific cron trigger by passing in the cron trigger id
const cron = await hatchet.cron.get(id);
...
// ? Delete
// You can delete a cron trigger by passing the cron object
// or a cron Id to the delete method
await hatchet.cron.delete(cron);
// !!

# Python SDK — Workflows and tasks - Hatchet - Mintlify
created: 2026-03-25, last updated: 2026-04-12, [Read more](https://mintlify.wiki/hatchet-dev/hatchet/sdk/python/workflows-tasks)

A standalone task is the simplest way to define a unit of work.
Apply the `@hatchet.task()` decorator to a function and Hatchet wraps it in a single-task workflow.
...
@dag_workflow.task()
def step1(input: EmptyModel, ctx: Context) -> dict[str, int]:
return {"value": 10}
# Second task — runs after step1
@dag_workflow.task(parents=[step1])
def step2(input: EmptyModel, ctx: Context) -> dict[str, int]:
parent_value = ctx.task_output(step1)["value"]
return {"doubled": parent_value * 2}
...
`@workflow.task()` accepts the following parameters from `@hatchet.task()`: `name`, `schedule_timeout`, `execution_timeout`, `retries`, `rate_limits`, `backoff_factor`, `backoff_max_seconds`, `concurrency`, `desired_worker_labels`.
It does **not** accept the workflow-level parameters (`description`, `input_validator`, `on_events`, `on_crons`, `version`, `sticky`, `default_priority`, `default_filters`, `default_additional_metadata`) since those are set on the enclosing `hatchet.workflow()`.

